    "\n"
    "class ScienceMaterialsMechanics(ScienceFormMixin, Component):\n"
    '    display_name = "材料科学·应力—应变分析"\n'
    '    description = "可追溯的应力—应变分析；具体方法与前提见随仓库提供的手册。"\n'
