@pytest.mark.parametrize("convert", [False, True])
def test_prefer_forms_preserves_connected_unit_conversion_behavior(convert):
    from lfx.graph import Graph

    from components.materials_quality import MaterialMissingCheck, MaterialUnitCheck
    from examples.demo_source import MaterialDemoTable

    source = MaterialDemoTable().set(records_json='[{"x":1},{"x":2}]')
    unit = MaterialUnitCheck().set(
        input_table=source.build_table,
        ui_mode="json",
        source_units_json='{"x":"MPa"}',
        expected_units_json='{"x":"Pa"}',
        convert_values=convert,
    )
    target = MaterialMissingCheck().set(input_table=unit.build_converted_table, columns_json='["x"]')
    payload = Graph(start=source, end=target).dump(name="Connected conversion")
    updated, report = migrate(payload, prefer_forms=True)
    assert template(node_of(updated, "MaterialUnitCheck"))["ui_mode"]["value"] == (
        "form" if convert else "json"
    )
    if not convert:
        assert any(item["reason"] == "connected_output_unavailable_in_form" for item in report["fallbacks"])
    graph = Graph.from_payload(updated)
    for step in graph.start():
        assert not hasattr(step, "valid") or step.valid, step
    converted = graph.get_vertex(unit.get_id()).results["converted_table"]
    assert converted["x"].tolist() == ([1e6, 2e6] if convert else [])


def test_prefer_forms_current_json_graph_mechanics_numeric_parity():
    from lfx.graph import Graph

    from examples.demo_source import MaterialDemoTable
    from materials_quality.science.catalog import component_class

    source = MaterialDemoTable().set(
        records_json=json.dumps(
            [
                {"strain": x, "stress": y}
                for x, y in [(0, 0), (0.0004, 80), (0.0008, 160), (0.004, 250), (0.008, 260)]
            ]
        )
    )
    node = component_class("materials.mechanics")().set(
        input_table=source.build_table,
        ui_mode="json",
        config_json='{"strain_unit":"fraction","stress_unit":"MPa","fit_range":[0,0.0008]}',
    )
    payload = Graph(start=source, end=node).dump(name="Legacy mechanics parity")
    updated, _ = migrate(payload, prefer_forms=True)
    results = []
    for candidate in (payload, updated):
        graph = Graph.from_payload(candidate)
        for step in graph.start():
            assert not hasattr(step, "valid") or step.valid, step
        results.append(graph.get_vertex(node.get_id()).results["report"].data["data"])
    for result in results:
        result["transform"].pop("parameters")  # Explicit native defaults are recorded for traceability.
    assert results[0] == results[1]


def test_prefer_forms_model_graph_keeps_one_training_call(monkeypatch):
    from lfx.graph import Graph

    from materials_quality.science import stats_models

    original_fit = stats_models.fit_model
    calls = []

    def counted(*args, **kwargs):
        calls.append(kwargs.get("default", "linear"))
        return original_fit(*args, **kwargs)

    monkeypatch.setattr(stats_models, "fit_model", counted)
    updated, _ = migrate(old_payload("examples/science_flows/08-model.json"), prefer_forms=True)
    graph = Graph.from_payload(updated)
    for step in graph.start():
        assert not hasattr(step, "valid") or step.valid, step
    prediction = graph.get_vertex("ScienceStatsPredict-predict").results["report"].data
    assert prediction["data"]["method"] == "saved_model_prediction"
    assert calls == ["linear"]


def test_prefer_forms_malformed_json_and_future_custom_code_never_execute(tmp_path):
    from materials_quality.science.catalog import component_class

    vertex = (
        component_class("materials.mechanics")().set(ui_mode="json", config_json="{broken").to_frontend_node()
    )
    payload = {"data": {"nodes": [vertex], "edges": []}}
    updated, report = migrate(payload, prefer_forms=True)
    assert template(updated["data"]["nodes"][0])["config_json"]["value"] == "{broken"
    assert report["fallbacks"][0]["reason"] == "malformed_config_json"
    marker = tmp_path / "old-source-was-executed"
    template(vertex)["code"]["value"] += (
        f"\nfrom pathlib import Path\nPath({str(marker)!r}).write_text('executed')\n"
    )
    updated, report = migrate(payload, prefer_forms=True)
    assert updated == payload and not marker.exists()
    assert report["skipped"][0]["reason"] == "custom_code"


def test_prefer_forms_cli_opt_in_reports_forms_and_preserves_source(tmp_path):
    source = tmp_path / "old.json"
    source.write_text(
        json.dumps(old_payload("examples/science_flows/05-mechanics-thermal.json")), encoding="utf-8"
    )
    before = source.read_bytes()
    done = subprocess.run(
        [sys.executable, str(ROOT / "scripts/migrate_flow_ui.py"), str(source), "--prefer-forms"],
        cwd=ROOT,
        encoding="utf-8",
        capture_output=True,
    )
    assert done.returncode == 0, done.stderr
    assert json.loads(done.stdout)["forms"]
    assert source.read_bytes() == before


@pytest.mark.parametrize("mutation", ["id", "template", "edge"])
def test_prefer_forms_malformed_graph_is_rejected_without_mutation(mutation):
    from materials_quality.science.flow_migration import MigrationError

    payload = old_payload("examples/science_flows/03-images.json")
    if mutation == "id":
        payload["data"]["nodes"][0].pop("id")
    elif mutation == "template":
        payload["data"]["nodes"][0]["data"]["node"]["template"] = []
    else:
        payload["data"]["edges"][0] = None
    before = copy.deepcopy(payload)
    with pytest.raises(MigrationError):
        migrate(payload, prefer_forms=True)
    assert payload == before


